(function(){
  const D = window.LMS_ICON_DATA;
  class LmsIcon extends HTMLElement {
    static get observedAttributes(){ return ['name','size']; }
    constructor(){ super(); this._r = this.attachShadow({mode:'open'}); }
    connectedCallback(){ this.render(); }
    attributeChangedCallback(){ this.render(); }
    render(){
      if(!this._r) return;
      const n = this.getAttribute('name');
      const s = this.getAttribute('size') || 24;
      const d = D[n];
      const host = ':host{display:inline-flex;align-items:center;justify-content:center;flex:none;width:'+s+'px;height:'+s+'px;line-height:0}svg{display:block}';
      this._r.innerHTML = '<style>'+host+'</style>' + (d ? '<svg width="'+s+'" height="'+s+'" viewBox="'+d.viewBox+'" fill="none">'+d.body+'</svg>' : '');
    }
  }
  if(!window.customElements.get('lms-icon')) window.customElements.define('lms-icon', LmsIcon);
})();
